    [4763] = {xp=1700, mob={{0, 0, 1, 0}}, objs={"薩巴克希斯的惡魔之包"}, items={12346, 12341, 12342, 12343, 12347}, d="在空的淨化碗裡盛滿奧伯丁月井的井水。\n在黑木熊怪的北部營地裡收集水果、堅果和榖物各一份。\n將水和三種食物混合起來，放置在壁泉河附近的營火邊，這樣就會召來喚引誘熊怪墮落的薩特。\n取回墮落護符，將它交給奧伯丁的桑迪斯·織風。", n="黑木熊怪的墮落", lvl=18, min=15, ps={4762}},
    [4811] = {xp=490, mob={{0, 0, 1, 0}}, objs={"神秘的紅色水晶"}, d="到奧伯丁的東邊去，沿著黑海岸東部邊界的山脈尋找一顆巨大的紅色水晶，然後向奧伯丁的哨兵戈琳達·納希恩彙報你的發現。", n="紅色水晶", lvl=14, min=12, fol={4812}},
    [4812] = {xp=490, mob={{0, 0, 1, 0}}, objs={"奧伯丁月井"}, items={14338}, d="在奧伯丁月井中把空水瓶裝滿，然後調查黑海岸東部山脈的紅水晶。", n="清洗水晶", lvl=14, min=12, ps={4811}, fol={4813}, chain=true},
    [4813] = {xp=980, d="向奧伯丁的哨兵哨兵戈琳達·納希恩報告你的發現。", n="水晶中的碎骨", lvl=14, min=12, ps={4812}},
    [4842] = {xp=5800, d="根據多諾瓦·雪山的指示行動，然後回到她那裏報告。", n="奇怪的源頭", lvl=56, min=51, ps={980}},
    [4861] = {xp=3200, d="在冬泉谷的南部尋找加隆·石矛的被破壞的營帳，以及他的補給物資。", n="被激怒的梟獸", lvl=59, min=53, fol={4863}},
