    [4864] = {xp=6400, mob={{0, 0, 1, 0}, {58.1, 6, 2, 0}}, tgo={{}, {"瘋狂的梟獸", "月光梟獸", "狂暴梟獸", "伊露恩的衛士"}}, objs={"加隆的補給物資"}, d="從雪地中拾起加隆的補給物資，然後尋找盜取加隆所說的護符的梟獸。\n將加隆的補給物資和藍色羽毛護符交給冬泉谷的加隆·石矛。", n="被激怒的梟獸", lvl=59, min=53, ps={4863}},
    [4901] = {xp=4800, d="在蘭莎爾拉嘗試激活艾露恩祭壇的過程中保護她。然後將你的發現報告給魯瑟蘭村的艾瑞拉斯·琥珀。", n="祭壇守護者", lvl=59, min=52, ps={979}, fol={4902}},
    [4902] = {xp=6000, d="與達納蘇斯的大德魯伊範達爾·鹿盔談一談。", n="艾露恩的梟獸", lvl=57, min=52, ps={4901}},
    [4906] = {xp=5450, mob={{53.5, 8, 1, 0}, {52.5, 8, 1, 0}, {52.5, 8, 1, 0}, {55, 1, 1, 0}}, tgo={{"碧火喚魔者"}, {"碧火背叛者"}, {"碧火欺詐者"}, {"薩瓦里克"}}, d="費伍德森林的艾瑞丹·藍風要你去殺掉8個碧火喚魔者、8個碧火背叛者、8個碧火欺詐者和薩瓦裏克。任務完成之後回到艾瑞丹那裏復命。", n="更深重的墮落", lvl=54, min=49, ps={4421}},
    [4971] = {xp=5800, mob={{56, 15, 1, 0}}, tgo={{"時光寄生蟲"}}, items={12627}, d="在安多哈爾的壹處倉庫附近使用時光置換器，使時光寄生蟲現身。\n殺掉15只時光寄生蟲，然後將時光置換器還給西瘟疫之地安多哈爾旅店的克羅米。", n="時間問題", lvl=56, min=53},
    [4984] = {xp=4100, mob={{53.5, 8, 1, 0}}, tgo={{"生病的狼"}}, d="消滅8只生病的狼，然後去找西瘟疫之地嚎哭鬼屋的穆格雷斯·深水。", n="大自然的苦楚", lvl=54, min=51, fol={4985}},
    [4985] = {xp=4350, mob={{55.5, 8, 1, 0}}, tgo={{"生病的灰熊"}}, d="消滅8只生病的灰熊，然後去找西瘟疫之地嚎哭鬼屋的穆格雷斯·深水。", n="大自然的苦楚", lvl=56, min=51, ps={4984}, fol={4986}},
    [4986] = {xp=5800, items={12663}, d="根據雕文橡木枝上面所附加的魔法，這個牛頭人德魯伊本來準備把它交給達納蘇斯的塞納裏奧議會。看來你應該到那裏去找壹個德魯伊，並尋求他的幫助。", n="雕文橡木枝", lvl=56, min=51, ps={4985}},
    [5021] = {xp=2550, d="這個女人的幽靈告訴你她要送出壹只包裹。她說那只包裹就在她的馬旁邊。至於馬在哪裏或者包裹要送到哪裏去，她卻根本沒有說。", n="遲到總比不到好", lvl=52, min=50, fol={5022}},
    [5022] = {xp=2550, items={12724}, d="與暴風城的皇家代理人巴瑟羅爾協商，查找到艾瑪·費爾斯通的下落。通常在市政廳裏都有壹個人口普查官。", n="遲到總比不到好", lvl=52, min=50, ps={5021}, fol={5048}, chain=true},
    [5048] = {xp=5100, items={12724}, d="找到暴風城的艾瑪並弄清她是否就是艾瑪·費爾斯通。如果是的話，那麽她可能想要拿到詹妮絲·費爾斯通給她的包裹。", n="善良的艾瑪", lvl=52, min=50, ps={5022}, fol={5050}},
    [5050] = {xp=2550, items={12721}, d="把半個好運護符還給西瘟疫之地的詹妮絲·費爾斯通。", n="好運護符", lvl=52, min=50, ps={5048, 5049}},
    [5066] = {xp=470, d="找到指揮官阿什拉姆·瓦羅菲斯特。他的大本營位於奧特蘭克山脈以北的冰風崗。", n="戰鬥的號角：瘟疫之地！", lvl=50, min=50, ex={5090, 5091}, fol={5092}, chain=true},
