    [5097] = {xp=5800, mob={{1, 6, 1, 0}, {1, 6, 1, 0}, {1, 6, 1, 0}, {1, 6, 1, 0}}, tgo={{"安多哈爾一號哨塔"}, {"安多哈爾二號哨塔"}, {"安多哈爾三號哨塔"}, {"安多哈爾四號哨塔"}}, items={12815}, d="使用信號火炬為安多哈爾城中的四座哨塔做上標記，你必須站在哨塔門口才能成功地進行標記。\n在做完了標記之後，將信號火炬還給西瘟疫之地冰風崗的指揮官阿什拉姆·瓦羅菲斯特。", n="標記哨塔", lvl=56, min=50, ps={5092}},
