    [5544] = {xp=5800, mob={{55.5, 15, 2, 0}}, tgo={{"腐肉蟲", "腐肉吞噬者"}}, d="在東瘟疫之地搜索腐肉蟲和腐肉吞噬者。殺了它們並收集它們的肉。當你收集到15塊食腐蟲肉塊之後，就回到提裏奧·弗丁那裏。", n="腐肉蟲", lvl=56, min=52, fol={5742}},
    [5545] = {xp=780, mob={{0, 0, 1, 0}}, objs={"一捆木柴"}, d="收集8捆木材，把它們交給東谷伐木場的管理員萊琳。", n="木材危機", lvl=9, min=5},
    [5601] = {xp=560, d="在達隆郡裏找到帕米拉·雷德帕斯。", n="小妹妹帕米拉", lvl=55, min=50, ex={5142}, fol={5149}, chain=true},
    [5713] = {xp=1050, d="保護哨兵阿娜莎，然後向梣谷邁斯特拉崗哨的奧奈雅報告。", n="見一個殺一個", lvl=15, min=10},
    [5742] = {xp=580, mob={{61, 6, 1, 1}}, tgo={{"提里恩·弗丁"}}, d="聽聽提裏奧·弗丁要說什麽。", n="救贖", lvl=56, min=52, pg={5542, 5543, 5544}, fol={5781}},
    [5762] = {xp=1250, items={14542}, d="將克拉維爾的箱子送到荊棘谷的赫米特·奈辛瓦里那裡。", n="赫米特·奈辛瓦里", lvl=31, min=28},
    [5781] = {xp=6000, mob={{57, 6, 2, 0}}, tgo={{"米庫提奧·骯髒吞嚥者"}}, d="到東瘟疫之地最南端的墓室去找回泰蘭之錘。完成目標之後，返回提裏奧·弗丁那裏。", n="遺忘的記憶", lvl=57, min=52, ps={5742}, fol={5845}},
    [5845] = {xp=6200, mob={{0, 0, 1, 0}}, objs={"失落榮耀的象徵"}, d="到東瘟疫之地東北部的北谷去，找到失落榮耀的象征。完成目標之後向提裏奧·弗丁復命。", n="失落的榮耀", lvl=58, min=52, ps={5781}, fol={5846}, chain=true},
    [5846] = {xp=6200, d="到凱爾達隆島去，尋找關於那副畫的線索。凱爾達隆島在瘟疫之地南部的湖中央。", n="愛與家庭", lvl=58, min=52, ps={5845}, fol={5848}, chain=true},
    [5848] = {xp=6600, mob={{0, 0, 1, 0}}, objs={"未完成的油畫"}, d="到瘟疫之地北部的斯坦索姆去。你可以在血色十字軍堡壘中找到\"愛與家庭\"這幅畫，它被隱藏在另壹幅描繪兩個月亮的畫之後。\n把這幅畫還給提裏奧·弗丁。", n="愛與家庭", lvl=60, min=52, ps={5846}},
    [5863] = {xp=4550, mob={{47, 10, 1, 0}, {46.5, 10, 1, 0}, {49, 1, 1, 0}}, tgo={{"砂槌蠻兵"}, {"砂槌執行者"}, {"掠奪者格瑪洛克"}}, d="加基森的安迪·利恩想要你攻入砂槌營地，殺死10個砂槌蠻兵、10個砂槌執行者，以及掠奪者格瑪洛克。", n="砂槌巨魔", lvl=49, min=44},
    [5903] = {xp=5650, mob={{0, 0, 1, 0}}, objs={"大白蟻丘"}, items={15042}, d="在東瘟疫之地的蟻丘上使用空的白蟻瓶。當你收集了100只瘟疫白蟻之後，就回到西瘟疫之地的冰風崗去找納薩尼爾·杜馬。", n="瘟疫與妳", lvl=55, min=48, fol={5904}, chain=true},
    [5904] = {xp=2800, items={15044}, d="到西瘟疫之地的北山伐木場去找個合適的地方，在那裏放下壹桶瘟疫白蟻。", n="瘟疫與妳", lvl=55, min=48, ps={5903}, fol={6389}},
    [6001] = {races=8, xp=840, mob={{13, 6, 1, 0}}, tgo={{"月爪梟獸的靈魂"}}, items={15208}, d="使用奧伯丁的月夜梟獸之石上面的塞納里奧月塵引出月爪梟獸，然後擊敗月爪梟獸並吸取它所擁有的身心之力。\n任務完成之後，與達納蘇斯的瑪斯雷·馭熊者談話。", n="身心之力", lvl=10, min=10, ps={5931}},
    [6004] = {xp=5800, mob={{53, 2, 1, 0}, {52.5, 2, 1, 0}, {55.5, 2, 1, 0}, {54.5, 2, 1, 0}}, tgo={{"血色醫護員"}, {"血色獵人"}, {"血色法師"}, {"血色騎士"}}, d="殺死2個血色醫護員、2個血色獵人、2個血色魔法師和2個血色騎士，然後回到西瘟疫之地的科爾斯塔·迪普沙東那兒。", n="未竟的事業", lvl=56, min=50, fol={6023}},
    [6021] = {xp=4200, mob={{54.5, 6, 2, 0}}, tgo={{"流亡者塞達爾"}}, d="將塞達爾的頭顱交給聖光之願禮拜堂的護理者奧林。", n="流亡者塞達爾", lvl=55, min=50},
    [6023] = {xp=6000, mob={{56, 6, 1, 0}, {57, 6, 1, 0}}, tgo={{"獵人萊德雷"}, {"騎士杜爾根"}}, d="殺掉獵人萊德雷和騎士杜爾根，然後向西瘟疫之地的科爾斯塔·迪普沙東復命。", n="未完的任務", lvl=57, min=50, ps={6004}, fol={6025}},
    [6024] = {xp=6600, mob={{60, 6, 2, 0}}, tgo={{"滲透者哈米亞"}}, d="殺了滲透者哈米亞，用他的鑰匙開啟墓室後的壹堆泥土。", n="哈米亞的請求", lvl=60, min=54},
    [6025] = {xp=6200, d="進入壁爐谷並找壹處高地，你可以在那裏觀察整個城鎮並估算血色十字軍的兵力，然後向西瘟疫之地的科爾斯塔·迪普沙東回報。", n="未完的任務", lvl=58, min=50, ps={6023}},
    [6028] = {xp=2550, items={15788}, d="把永望鎮報告送給西瘟疫地冰風崗的銀色黎明軍官普爾哈特。", n="永望鎮報告", lvl=52, min=50},
    [6030] = {xp=2550, items={15790}, d="將《靈語研究》這本書交給東瘟疫之地聖光之願禮拜堂的尼古拉斯·瑟倫霍夫公爵。", n="尼古拉斯·瑟倫霍夫公爵", lvl=52, min=50},
    [6063] = {races=8, xp=840, mob={{5.5, 6, 1, 0}}, tgo={{"樹林潛伏者"}}, items={15921}, d="使用馴獸棒馴服樹林潛伏者。練習你的技能，然後將馴獸棒還給多蘭納爾的達札拉。", n="馴服野獸", lvl=10, min=10, ex={94013}, fol={6101}},
