    [6185] = {xp=8300, mob={{0, 0, 1, 0}, {0, 0, 1, 0}, {0, 0, 1, 0}}, objs={"破碎的人類殘骸"}, d="搜尋東瘟疫之地，尋找\"雕零者\"的線索以及失蹤的軍情七處密探。如果你找到任何軍情七處徽章，就把它們交給冰風崗的弗林特·沙多摩爾。", n="東部的瘟疫", lvl=60, min=56, ps={6184}},
    [6341] = {races=8, xp=210, items={16262}, d="將尼莎的貨物交給維斯派塔斯。", n="泰達希爾的漁業", lvl=10, min=10, fol={6342}},
