    [6389] = {xp=5650, items={15044}, d="使用北山伐木場裏的鐵棍放出那裏的瘟疫白蟻，然後向西瘟疫之地冰風崗的納薩尼爾·杜馬報告。", n="瘟疫與妳", lvl=55, min=48, ps={5904}},
    [6391] = {races=68, xp=420, items={16310}, d="從獅鷲獸管理員索格拉姆·伯雷森那裡租一隻獅鷲獸飛往鐵爐堡，然後將布洛克的名單交給鐵爐堡的高尼爾·石趾。", n="飛往鐵爐堡", lvl=10, min=10, ps={6387}, fol={6388}},
    [6392] = {races=68, xp=1050, items={16311}, d="從獅鷲獸管理員格萊斯·瑟登那裡租用一頭飛往塞爾薩瑪的獅鷲獸，然後將榮譽鋤交給塞爾薩瑪的布洛克·尋石者。", n="向布洛克回復", lvl=10, min=10, ps={6388}},
