    [7383] = {xp=660, mob={{0, 0, 1, 0}}, objs={"神諭林地月井"}, items={18152}, d="用月井的水裝滿紫水晶瓶，然後把它交給多蘭納爾的科瑞薩斯·月怒。", n="大地之冠", lvl=11, min=1, ps={933}, ex={934}, fol={935}},
    [7701] = {xp=4700, mob={{50, 6, 2, 1}}, tgo={{"監督者瑪托留斯"}}, d="那個叫做工頭瑪托留斯的黑鐵矮人叛徒就藏在大熔爐的熔渣之池深處。\n殺死工頭瑪托留斯，將他的頭顱交給灼熱峽谷的偵查隊長洛洛爾以換取你的獎勵。", n="懸賞：工頭瑪托留斯", lvl=50, min=45},
    [7722] = {xp=4700, mob={{0, 0, 1, 0}}, objs={"秘密設計圖:熾熱助熔劑"}, d="在大熔爐的熔渣之池中的某個地方，你可以找到工頭瑪托留斯偷走的秘密設計圖：熾熱助熔劑。找到這些設計圖，把它們還給灼熱峽谷的大鐵匠博恩奈特。", n="絕密配方！", lvl=50, min=45},
    [7723] = {xp=4550, mob={{48, 20, 1, 0}}, tgo={{"重型作戰傀儡"}}, d="漢瑟爾·重拳讓你殺掉20個重型作戰傀儡。\n重型作戰傀儡就在灼熱峽谷的大熔爐附近。當你殺死足夠多的傀儡後，就回去找漢瑟爾·重拳。", n="該死的胖手指！", zt="該死的手指頭！", lvl=49, min=45},
    [7724] = {xp=4550, mob={{48, 20, 1, 0}}, tgo={{"灼熱熔岩蜘蛛"}}, d="漢瑟爾·重拳要你殺死灼熱峽谷中的20只巨型熔巖蜘蛛。你可以在灼熱峽谷的高地和熔巖池裏找到巨型熔巖蜘蛛。\n當你殺死足夠的巨型熔巖蜘蛛之後，回到漢瑟爾·重拳那裏復命。", n="熔岩蜘蛛的威脅！", zt="熔巖蜘蛛的威脅！", lvl=49, min=45},
    [7727] = {xp=4550, mob={{48, 20, 1, 0}}, tgo={{"燻火龍"}}, d="漢瑟爾·重拳讓你去殺掉20個熏火龍。\n熏火龍侵占了熔渣之池中的那些巖漿池。熔渣之池就在灼熱峽谷的大熔爐中。\n當你殺死足夠數量的熏火龍後，就回去找漢瑟爾·重拳。", n="燻火龍", zt="熏火龍", lvl=49, min=45},
    [7728] = {xp=4400, mob={{46.5, 6, 2, 0}, {47.5, 6, 2, 0}}, tgo={{"黑鐵鍛造師"}, {"黑鐵監視者"}}, d="找到冶煉鼓風機和偵查員的望遠鏡，把它們還給灼熱峽谷的監工斯克蘭格。\n你所知道的關於這些物品的惟壹信息是：它們肯定是被黑鐵矮人偷走的。冶煉鼓風機是鐵匠用的鍛造工具，偵查員的望遠鏡是偵查員所需的偵查工具。", n="被盜：鼓風機和望遠鏡", lvl=48, min=45},
    [7729] = {xp=4400, mob={{47.5, 15, 1, 0}, {45.5, 15, 1, 0}}, tgo={{"黑鐵監工"}, {"黑鐵奴隸販子"}}, d="殺死15個黑鐵工頭和15個黑鐵奴隸販子。完成任務之後就回去找監工斯克蘭格。", n="工作機會：肅清競爭對手", lvl=48, min=45},
    [7733] = {xp=4400, mob={{47.1, 10, 2, 0}}, tgo={{"狂暴的怒痕雪人", "老年怒痕雪人", "殘忍的怒痕雪人", "潛伏的深痕雪人"}}, d="把10塊怒痕雪人的毛皮交給菲拉斯羽月要塞的普拉特·馬克格魯比。", n="更高的品質", lvl=48, min=40, ps={2821}},
    [7735] = {xp=2200, items={18969}, d="把原始雪人毛皮交給菲拉斯羽月要塞的普拉特·馬克格魯比。", n="原始雪人毛皮", lvl=48, min=40, ps={2821}},
    [7791] = {xp=660, mob={{0, 0, 1, 0}}, objs={"奧特蘭克花崗岩", "破爛的箱子", "破損的箱子"}, n="捐獻毛料", lvl=60, min=12},
